preConditionHook:
rrange = high[0] - low[0];
// EL: average() and stddev() read the rrange VARIABLE's own history, and a
// variable holds its initial 0 for every bar before the strategy's first
// evaluated one. Recomputing the mean from price instead would use warm-up
// bars EasyLanguage never saw, so the history is mirrored here -- a ring
// buffer that starts zeroed. It is also re-seeded if the length ever changes,
// which is what WFSafe_SummationFC does for the same reason.
if (rangeHistory.size() != (std::size_t)(int)lookback) {
    rangeHistory.assign((std::size_t)(int)lookback, 0.0);
    rangeCursor = 0;
}
rangeHistory[rangeCursor] = rrange;
rangeCursor = (rangeCursor + 1) % rangeHistory.size();
rangeMean = 0.0;
for (double v : rangeHistory) {
    rangeMean += v;
}
rangeMean /= (int)lookback;
// Population standard deviation (divide by N): EasyLanguage's definition.
rangeStd = 0.0;
for (double v : rangeHistory) {
    double d = v - rangeMean;
    rangeStd += d * d;
}
rangeStd = std::sqrt(rangeStd / (int)lookback);
